from __future__ import annotations
from typing import Any

from fastworkflow.utils.rlm_logger import rlm_log


class ObservationStore:
    """
    External key-value store for archiving raw tool observations that are too
    large to keep inline in the ReAct trajectory.

    Each entry holds:
      content     — the raw observation text
      description — a concise, human-readable note of what the content contains
                    (derived from the command's static output-field description)
      meta        — bookkeeping (tool name, args, step index)
    """

    def __init__(self):
        self._store: dict[str, dict[str, Any]] = {}

    def archive(self, key: str, content: str, description: str = "",
                meta: dict[str, Any] | None = None) -> str:
        # On a key collision the freshest content wins: the same command+params
        # can be re-run after a mutation (e.g. an order modified then re-fetched),
        # so keeping the stale entry would be a correctness bug.
        if key in self._store:
            existed_same = self._store[key]["content"] == content
            self._store[key] = {
                "content": content,
                "description": description or self._store[key].get("description", ""),
                "meta": meta or {},
            }
            rlm_log(f"\n{'#'*60}")
            rlm_log(f"[OBSERVATION STORE] key collision — {'reused (identical)' if existed_same else 'OVERWRITTEN with fresh content'}")
            rlm_log(f"  key: {key}")
            rlm_log(f"{'#'*60}\n")
            return key

        self._store[key] = {"content": content, "description": description, "meta": meta or {}}
        rlm_log(f"\n{'#'*60}")
        rlm_log(f"[OBSERVATION STORE] new entry archived")
        rlm_log(f"  key          : {key}")
        rlm_log(f"  description   : {description}")
        rlm_log(f"  content       : {content[:300]}{'...' if len(content) > 300 else ''}")
        rlm_log(f"  total entries : {len(self._store)}")
        rlm_log(f"  all keys      : {list(self._store.keys())}")
        rlm_log(f"{'#'*60}\n")
        return key

    def get(self, key: str) -> str | None:
        entry = self._store.get(key)
        content = entry["content"] if entry else None
        rlm_log(f"\n{'~'*60}")
        rlm_log(f"[OBSERVATION STORE] dereference requested")
        rlm_log(f"  key      : {key}")
        rlm_log(f"  found    : {entry is not None}")
        rlm_log(f"{'~'*60}\n")
        return content

    def description(self, key: str) -> str:
        entry = self._store.get(key)
        return entry.get("description", "") if entry else ""

    def all_keys(self) -> list[str]:
        return list(self._store.keys())

    def items(self) -> list[dict[str, Any]]:
        """Return all entries as a list of {id, description, content} records."""
        return [
            {"id": k, "description": v.get("description", ""), "content": v["content"]}
            for k, v in self._store.items()
        ]

    def __len__(self) -> int:
        return len(self._store)
